/*
 * Trips: when each vehicle runs, grouped by the stop pattern it serves.
 *
 * GENERATED — do not edit by hand; re-run `pnpm --filter api generate:trips`.
 *
 * A pattern is the ordered stop list several trips share — RAPTOR's "route",
 * which is not a line: line M runs six patterns once short-turns are counted.
 *
 * Times are seconds since local midnight and MAY EXCEED 86400 on a trip that
 * crosses it, so that a sequence stays monotonic. Compare against a departure
 * time in the same units rather than taking a modulus, or a 00:05 arrival
 * sorts before the 22:48 departure it follows.
 *
 * `s` is departure per stop, `d` the 3-bit WD|SAT|SUN day mask. `a` is
 * arrival per stop and is ABSENT where the feed does not record a real one —
 * KCI stores the terminus arrival on every row, so it is dropped rather than
 * misread as a per-stop time. Absent means unknown, never "same as departure".
 *
 * Only trips whose every hop matches a routable edge are here. Trips with
 * gaps in the feed are dropped rather than stitched — see generateTrips.ts.
 *
 * Measured 2026-09-06: importing this took the worker bundle from 875 KB /
 * 167 KB gz to 1287 KB / 244 KB gz. Comfortable against the 3 MB compressed
 * limit, but it is ~7x the largest hand-written data module here and it buys
 * nothing until the search reads it. If a fuller timetable lands (all-day
 * boards, holiday variants) this should move to a D1 read at graph load —
 * the graph is already memoised per isolate, so it would amortise exactly
 * the way getGraphInputs does.
 */

/** One trip: departures per stop, optional arrivals, and the days it runs. */
export interface TripTimes {
  t: string
  d: number
  s: number[]
  a?: number[]
}

/** One stop pattern and every trip that serves it. */
export interface TripPattern {
  line: string
  stations: string[]
  trips: TripTimes[]
}

